(* [comment removed for export] *)
Ltac accok_fp_on ::= fail.

(* [comment removed for export] *)
Definition PMA1_STOPS : list Z :=
  [e_stack_malloc 0%nat; e_selGetParameters; e_pixResizeImageData; e_pixClone; e_pixCreateTemplate_po; e_returnErrorPtr; e_pixCopy_po;
   pma1_br; pma1_fl].

Definition PMA1_CALLS : list Z :=
